import{_ as p,a0 as o,w as d,s as r,I as t,x as i,a1 as a,A as l,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"怎样在 Ubuntu Linux 上安装 MySQL | LCTT x X-CMD","titleTemplate":false,"description":"怎样在 Ubuntu Linux 上安装 MySQL | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎样在 Ubuntu Linux 上安装 MySQL | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎样在 Ubuntu Linux 上安装 MySQL | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20190416 How to Install MySQL in Ubuntu Linux","title":"怎样在 Ubuntu Linux 上安装 MySQL","tag":"201904","desc":""},"relativePath":"201904/20190416 How to Install MySQL in Ubuntu Linux.md","filePath":"[post].md"}'),u={name:"201904/20190416 How to Install MySQL in Ubuntu Linux.md"};function h(g,s,b,k,y,m){const e=o("Link");return d(),r("div",null,[s[28]||(s[28]=t("h1",{id:"怎样在-ubuntu-linux-上安装-mysql",tabindex:"-1"},[i("怎样在 Ubuntu Linux 上安装 MySQL "),t("a",{class:"header-anchor",href:"#怎样在-ubuntu-linux-上安装-mysql","aria-label":"Permalink to “怎样在 Ubuntu Linux 上安装 MySQL”"},"​")],-1)),s[29]||(s[29]=t("blockquote",null,[t("p",null,"本教程教你如何在基于 Ubuntu 的 Linux 发行版上安装 MySQL。对于首次使用的用户，你将会学习到如何验证你的安装和第一次怎样去连接 MySQL。")],-1)),t("p",null,[a(e,{href:"https://www.mysql.com/"},{default:l(()=>[...s[0]||(s[0]=[i("MySQL",-1)])]),_:1}),s[2]||(s[2]=i(" 是一个典型的数据库管理系统。它被用于许多技术栈中，包括流行的 ",-1)),a(e,{href:"https://en.wikipedia.org/wiki/LAMP_(software_bundle)"},{default:l(()=>[...s[1]||(s[1]=[i("LAMP",-1)])]),_:1}),s[3]||(s[3]=i(" （Linux、Apache、MySQL、PHP）技术栈。它已经被证实了其稳定性。另一个让 MySQL 受欢迎的原因是它是开源的。",-1))]),s[30]||(s[30]=n('<p>MySQL 是关系型数据库（基本上是表格数据）。以这种方式它很容易去存储、组织和访问数据。它使用SQL（结构化查询语言）来管理数据。</p><p>这这篇文章中，我将向你展示如何在 Ubuntu 18.04 安装和使用 MySQL 8.0。让我们一起来看看吧！</p><h3 id="在-ubuntu-上安装-mysql" tabindex="-1">在 Ubuntu 上安装 MySQL <a class="header-anchor" href="#在-ubuntu-上安装-mysql" aria-label="Permalink to “在 Ubuntu 上安装 MySQL”">​</a></h3><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/04/install-mysql-ubuntu.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>我将会介绍两种在 Ubuntu 18.04 上安装 MySQL 的方法：</p><ol><li>从 Ubuntu 仓库上安装 MySQL。非常简单，但不是最新版（5.7）</li><li>从官方仓库安装 MySQL。你将额外增加一些步处理过程，但不用担心。你将会拥有最新版的MySQL（8.0）</li></ol><p>有必要的时候，我将会提供屏幕截图去引导你。但这篇文章中的大部分步骤，我将直接在终端（默认热键： <code>CTRL+ALT+T</code>）输入命令。别害怕！</p><h4 id="方法-1、从-ubuntu-仓库安装-mysql" tabindex="-1">方法 1、从 Ubuntu 仓库安装 MySQL <a class="header-anchor" href="#方法-1、从-ubuntu-仓库安装-mysql" aria-label="Permalink to “方法 1、从 Ubuntu 仓库安装 MySQL”">​</a></h4><p>首先，输入下列命令确保你的仓库已经被更新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>现在，安装 MySQL 5.7，简单输入下列命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install mysql-server -y</span></span></code></pre></div><p>就是这样！简单且高效。</p><h4 id="方法-2、使用官方仓库安装-mysql" tabindex="-1">方法 2、使用官方仓库安装 MySQL <a class="header-anchor" href="#方法-2、使用官方仓库安装-mysql" aria-label="Permalink to “方法 2、使用官方仓库安装 MySQL”">​</a></h4><p>虽然这个方法多了一些步骤，但我将逐一介绍，并尝试写下清晰的笔记。</p>',15)),t("p",null,[s[5]||(s[5]=i("首先浏览 MySQL 官方网站的",-1)),a(e,{href:"https://dev.mysql.com/downloads/repo/apt/"},{default:l(()=>[...s[4]||(s[4]=[i("下载页面",-1)])]),_:1}),s[6]||(s[6]=i("。",-1))]),s[31]||(s[31]=t("p",null,[t("img",{src:"https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_apt_download_page.jpg?fit=800%2C280&ssl=1",alt:""})],-1)),s[32]||(s[32]=t("p",null,"在这里，选择 DEB 软件包，点击“Download”链接。",-1)),s[33]||(s[33]=t("p",null,[t("img",{src:"https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_deb_download_link.jpg?fit=800%2C507&ssl=1",alt:""})],-1)),s[34]||(s[34]=t("p",null,"滑到有关于 Oracle 网站信息的底部，右键 “No thanks, just start my download.”，然后选择 “Copy link location”。",-1)),t("p",null,[s[8]||(s[8]=i("现在回到终端，我们将使用 ",-1)),a(e,{href:"https://linuxhandbook.com/curl-command-examples/"},{default:l(()=>[...s[7]||(s[7]=[i("Curl",-1)])]),_:1}),s[9]||(s[9]=i(" 命令去下载这个软件包：",-1))]),s[35]||(s[35]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>curl -OL https://dev.mysql.com/get/mysql-apt-config_0.8.12-1_all.deb</span></span></code></pre></div><p><code>https://dev.mysql.com/get/mysql-apt-config_0.8.12-1_all.deb</code> 是我刚刚从网页上复制的链接。根据当前的 MySQL 版本，它有可能不同。让我们使用 <code>dpkg</code> 去开始安装 MySQL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dpkg -i mysql-apt-config*</span></span></code></pre></div><p>更新你的仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>要实际安装 MySQL，我们将使用像第一个方法中同样的命令来安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install mysql-server -y</span></span></code></pre></div><p>这样做会在你的终端中打开包配置的提示。使用向下箭头选择“Ok”选项。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_package_configuration_ok.jpg?fit=800%2C587&amp;ssl=1" alt=""></p>',9)),t("p",null,[s[11]||(s[11]=i("点击回车。这应该会提示你输入密码：这是在为 MySQL 设置 root 密码。不要与 ",-1)),a(e,{href:"https://itsfoss.com/change-password-ubuntu/"},{default:l(()=>[...s[10]||(s[10]=[i("Ubuntu 的 root 密码混淆",-1)])]),_:1}),s[12]||(s[12]=i("。",-1))]),s[36]||(s[36]=n('<p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_enter_password.jpg?fit=800%2C583&amp;ssl=1" alt=""></p><p>输入密码然后点击 Tab 键去选择“Ok“。点击回车键，你将重新输入密码。操作完之后，再次键入 Tab 去选择 “Ok”。按下回车键。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_information_on_configuring.jpg?fit=800%2C581&amp;ssl=1" alt=""></p><p>将会展示一些关于 MySQL Server 的配置信息。再次按下 Tab 去选择 “Ok” 和按下回车键：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_default_authentication_plugin.jpg?fit=800%2C586&amp;ssl=1" alt=""></p><p>这里你需要去选择默认验证插件。确保选择了“Use Strong Password Encryption”。按下 Tab 键和回车键。</p><p>就是这样！你已经成功地安装了 MySQL。</p><h4 id="验证你的-mysql-安装" tabindex="-1">验证你的 MySQL 安装 <a class="header-anchor" href="#验证你的-mysql-安装" aria-label="Permalink to “验证你的 MySQL 安装”">​</a></h4><p>要验证 MySQL 已经正确安装，使用下列命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl status mysql.service</span></span></code></pre></div><p>这将展示一些关于 MySQL 服务的信息：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_service_information.jpg?fit=800%2C402&amp;ssl=1" alt=""></p><p>你应该在那里看到 “Active: active (running)”。如果你没有看到，使用下列命令去开始这个服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl start mysql.service</span></span></code></pre></div><h4 id="配置-保护-mysql" tabindex="-1">配置/保护 MySQL <a class="header-anchor" href="#配置-保护-mysql" aria-label="Permalink to “配置/保护 MySQL”">​</a></h4><p>对于刚安装的 MySQL，你应该运行它提供的安全相关的更新命令。就是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mysql_secure_installation</span></span></code></pre></div><p>这样做首先会询问你是否想使用 “<ruby>密码有效强度<rt>validate password component</rt></ruby>”。如果你想使用它，你将必须选择一个最小密码强度（0 – 低，1 – 中，2 – 高）。你将无法输入任何不遵守所选规则的密码。如果你没有使用强密码的习惯（本应该使用），这可能会配上用场。如果你认为它可能有帮助，那你就键入 <code>y</code> 或者 <code>Y</code>，按下回车键，然后为你的密码选择一个强度等级和输入一个你想使用的密码。如果成功，你将继续强化过程；否则你将重新输入一个密码。</p><p>但是，如果你不想要此功能（我不会），只需按回车或任何其他键即可跳过使用它。</p><p>对于其他选项，我建议开启它们（对于每一步输入 <code>y</code> 或者 <code>Y</code> 和按下回车）。它们（依序）是：“<ruby>移除匿名用户<rt>remove anonymous user</rt></ruby>”，“<ruby>禁止 root 远程登录<rt>disallow root login remotely</rt></ruby>”，“<ruby>移除测试数据库及其访问<rt>remove test database and access to it</rt></ruby>”。“<ruby>重新载入权限表<rt>reload privilege tables now</rt></ruby>”。</p><h4 id="链接与断开-mysql-server" tabindex="-1">链接与断开 MySQL Server <a class="header-anchor" href="#链接与断开-mysql-server" aria-label="Permalink to “链接与断开 MySQL Server”">​</a></h4><p>为了运行 SQL 查询，你首先必须使用 MySQL 连到服务器并在 MySQL 提示符使用。</p><p>执行此操作的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mysql -h host_name -u user -p</span></span></code></pre></div><ul><li><code>-h</code> 用来指定一个主机名（如果这个服务被安装到其他机器上，那么会有用；如果没有，忽略它）</li><li><code>-u</code> 指定登录的用户</li><li><code>-p</code> 指定你想输入的密码.</li></ul><p>虽然出于安全原因不建议，但是你可以在命令行最右边的 <code>-p</code> 后直接输入密码。例如，如果用户<code>test_user</code> 的密码是 <code>1234</code>，那么你可以在你使用的机器上尝试去连接，你可以这样使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mysql -u test_user -p1234</span></span></code></pre></div><p>如果你成功输入了必要的参数，你将会收到由 MySQL shell 提示符提供的欢迎（<code>mysql &gt;</code>）：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_shell_prompt-2.jpg?fit=800%2C423&amp;ssl=1" alt=""></p><p>要从服务端断开连接和离开 MySQL 提示符，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>QUIT</span></span></code></pre></div><p>输入 <code>quit</code> （MySQL 不区分大小写）或者 <code>\\q</code> 也能工作。按下回车退出。</p><p>你使用简单的命令也能输出关于版本的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mysqladmin -u root version -p</span></span></code></pre></div><p>如果你想看命令行选项列表，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mysql --help</span></span></code></pre></div><h4 id="卸载-mysql" tabindex="-1">卸载 MySQL <a class="header-anchor" href="#卸载-mysql" aria-label="Permalink to “卸载 MySQL”">​</a></h4><p>如果您决定要使用较新版本或只是想停止使用 MySQL。</p><p>首先，关闭服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl stop mysql.service &amp;&amp; sudo systemctl disable mysql.service</span></span></code></pre></div><p>确保你备份了你的数据库，以防你之后想使用它们。你可以通过运行下列命令卸载 MySQL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt purge mysql*</span></span></code></pre></div><p>清理依赖：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt autoremove</span></span></code></pre></div><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h3><p>在这篇文章中，我已经介绍如何在 Ubuntu Linux 上安装 Mysql。我很高兴如果这篇文章能帮助到那些正为此挣扎的用户或者刚刚开始的用户。</p><p>如果你发现这篇文章是一个很有用的资源，在评论里告诉我们。你为了什么使用 MySQL? 我们渴望收到你的任何反馈、印象和建议。感谢阅读，并毫不犹豫地尝试这个很棒的工具！</p><hr>',48)),t("p",null,[s[14]||(s[14]=i("via: ",-1)),a(e,{href:"https://itsfoss.com/install-mysql-ubuntu/"},{default:l(()=>[...s[13]||(s[13]=[i("https://itsfoss.com/install-mysql-ubuntu/",-1)])]),_:1})]),t("p",null,[s[19]||(s[19]=i("作者：",-1)),a(e,{href:"https://itsfoss.com/author/sergiu/"},{default:l(()=>[...s[15]||(s[15]=[i("Sergiu",-1)])]),_:1}),s[20]||(s[20]=i(" 选题：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[16]||(s[16]=[i("lujun9972",-1)])]),_:1}),s[21]||(s[21]=i(" 译者：",-1)),a(e,{href:"https://github.com/arrowfeng"},{default:l(()=>[...s[17]||(s[17]=[i("arrowfeng",-1)])]),_:1}),s[22]||(s[22]=i(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[18]||(s[18]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[25]||(s[25]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[23]||(s[23]=[i("LCTT",-1)])]),_:1}),s[26]||(s[26]=i(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:l(()=>[...s[24]||(s[24]=[i("Linux中国",-1)])]),_:1}),s[27]||(s[27]=i(" 荣誉推出",-1))])])}const S=p(u,[["render",h]]);export{L as __pageData,S as default};
